    <div class="todo-container">
        <div class="todo-header">
            <h1>Todo List</h1>
        </div>

        <div class="todo-input">
            <div class="input-group">
                <input type="text" id="todo-input" placeholder="Add a new todo..." maxlength="100">
                <button id="add-btn">Add</button>
            </div>
        </div>

        <div class="todo-filters">
            <button class="filter-btn active" data-filter="all">All</button>
            <button class="filter-btn" data-filter="active">Active</button>
            <button class="filter-btn" data-filter="completed">Completed</button>
        </div>

        <ul class="todo-list" id="todo-list">
            <!-- Todos will be inserted here -->
        </ul>

        <div class="todo-stats" id="todo-stats">
            <span id="items-left">0 items left</span>
            <button onclick="clearCompleted()" style="background: none; border: none; color: #667eea; cursor: pointer; text-decoration: underline;">Clear completed</button>
        </div>
    </div>

    <div id="toast" class="toast">Todo added successfully!</div>

    <script>
        // Todo App State
        let todos = [];
        let currentFilter = 'all';

        // DOM Elements
        const todoInput = document.getElementById('todo-input');
        const addBtn = document.getElementById('add-btn');
        const todoList = document.getElementById('todo-list');
        const todoStats = document.getElementById('todo-stats');
        const itemsLeft = document.getElementById('items-left');
        const filterBtns = document.querySelectorAll('.filter-btn');

        // Load todos from localStorage
        function loadTodos() {
            try {
                const stored = localStorage.getItem('todo-app-todos');
                if (stored) {
                    todos = JSON.parse(stored);
                }
            } catch (e) {
                console.error('Error loading todos:', e);
                todos = [];
            }
        }

        // Save todos to localStorage
        function saveTodos() {
            try {
                localStorage.setItem('todo-app-todos', JSON.stringify(todos));
            } catch (e) {
                console.error('Error saving todos:', e);
                showToast('Error saving to localStorage', true);
            }
        }

        // Show toast notification
        function showToast(message, isError = false) {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.className = 'toast' + (isError ? ' error' : '');
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }

        // Generate unique ID
        function generateId() {
            return Date.now().toString(36) + Math.random().toString(36).substr(2);
        }

        // Add new todo
        function addTodo(text) {
            if (!text.trim()) {
                showToast('Please enter a todo', true);
                return false;
            }

            const todo = {
                id: generateId(),
                text: text.trim(),
                completed: false,
                createdAt: Date.now()
            };

            todos.unshift(todo);
            saveTodos();
            renderTodos();
            showToast('Todo added successfully!');
            return true;
        }

        // Delete todo
        function deleteTodo(id) {
            todos = todos.filter(todo => todo.id !== id);
            saveTodos();
            renderTodos();
        }

        // Toggle todo completion
        function toggleTodo(id) {
            todos = todos.map(todo => {
                if (todo.id === id) {
                    return { ...todo, completed: !todo.completed };\n                }
                return todo;
            });
            saveTodos();
            renderTodos();
        }

        // Clear completed todos
        function clearCompleted() {
            const completedCount = todos.filter(todo => todo.completed).length;
            if (completedCount === 0) return;

            todos = todos.filter(todo => !todo.completed);
            saveTodos();
            renderTodos();
            showToast(`${completedCount} completed todos cleared!`);
        }

        // Filter todos
        function filterTodos(filter) {
            currentFilter = filter;
            filterBtns.forEach(btn => {
                btn.classList.toggle('active', btn.dataset.filter === filter);
            });
            renderTodos();
        }

        // Get filtered todos
        function getFilteredTodos() {
            switch (currentFilter) {
                case 'active':
                    return todos.filter(todo => !todo.completed);
                case 'completed':
                    return todos.filter(todo => todo.completed);
                default:
                    return todos;
            }
        }

        // Render todos
        function renderTodos() {
            const filteredTodos = getFilteredTodos();
            todoList.innerHTML = '';

            if (filteredTodos.length === 0) {
                const emptyState = document.createElement('li');
                emptyState.className = 'empty-state';
                emptyState.textContent = currentFilter === 'all' ? 
                    'No todos yet. Add one above!' : 
                    `No ${currentFilter} todos.`;
                todoList.appendChild(emptyState);
                return;
            }

            filteredTodos.forEach((todo, index) => {
                const todoItem = document.createElement('li');
                todoItem.className = 'todo-item';
                if (todo.completed) todoItem.classList.add('completed');

                todoItem.innerHTML = `
                    <div class="todo-content">
                        <div class="todo-checkbox ${todo.completed ? 'checked' : ''}" onclick="toggleTodo('${todo.id}')"></div>
                        <span class="todo-text" onclick="toggleTodo('${todo.id}')" ondblclick="editTodo('${todo.id}')">${escapeHtml(todo.text)}</span>
                    </div>
                    <button class="todo-delete" onclick="deleteTodo('${todo.id}')">
                        Delete
                    </button>
                `;

                todoList.appendChild(todoItem);
            });

            // Update stats
            const activeTodos = todos.filter(todo => !todo.completed).length;
            itemsLeft.textContent = `${activeTodos} ${activeTodos === 1 ? 'item' : 'items'} left`;
        }

        // Escape HTML to prevent XSS
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Edit todo (double click)
        function editTodo(id) {
            const todo = todos.find(t => t.id === id);
            if (!todo) return;

            const newText = prompt('Edit todo:', todo.text);
            if (newText !== null && newText.trim()) {
                todos = todos.map(t => {
                    if (t.id === id) {
                        return { ...t, text: newText.trim() };
                    }
                    return t;
                });
                saveTodos();
                renderTodos();
                showToast('Todo updated!');
            }
        }

        // Event Listeners
        addBtn.addEventListener('click', () => {
            const text = todoInput.value;
            if (addTodo(text)) {
                todoInput.value = '';
            }
        });

        todoInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                const text = todoInput.value;
                if (addTodo(text)) {
                    todoInput.value = '';
                }
            }
        });

        // Filter button event listeners
        filterBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                filterTodos(btn.dataset.filter);
            });
        });

        // Initialize app
        function init() {
            loadTodos();
            renderTodos();
        }

        // Start the app
        init();
    </script>
</body>
</html>"}
